// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CreativeCanvas) predicate.CreativeCanvas {
	return predicate.CreativeCanvas(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CreativeCanvas) predicate.CreativeCanvas {
	return predicate.CreativeCanvas(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CreativeCanvas) predicate.CreativeCanvas {
	return predicate.CreativeCanvas(sql.NotPredicates(p))
}
